 * TOML parser that outputs either JSON or keys list
 */

import { readFileSync } from 'fs'

const mode = process.argv[2]

if (!mode || !['json', 'keys'].includes(mode)) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch (e) {
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}

// Parse TOML
const parser = new TomlParser(input)
let doc

try {
  doc = parser.parse()
} catch (err) {
  process.stderr.write(err.message + '\n')
  process.exit(2)
}

if (mode === 'json') {
  process.stdout.write(toJSON(doc) + '\n')
} else {
  process.stdout.write(toKeys(doc))
}
process.exit(0)

// ============================================================================

class TomlParser {
  constructor(input) {
    this.lines = input.split('\n')
    // Drop empty tail if there's a trailing newline
    if (this.lines.length > 0 && this.lines[this.lines.length - 1] === '') {
      this.lines.pop()
    }
    this.lineNum = 0
    this.root = {}
    this.current = this.root
    this.currentPath = []
  }

  parse() {
    for (this.lineNum = 0; this.lineNum < this.lines.length; this.lineNum++) {
      const line = this.lines[this.lineNum]
      this.parseLine(line)
    }
    return this.root
  }

  parseLine(line) {
    // Remove comment and trailing whitespace
    line = this.stripComment(line)
    line = line.trimEnd()

    // Skip blank lines
    if (line.trim() === '') {
      return
    }

    const firstNonWs = line.search(/\S/)
    if (firstNonWs === -1) {
      return // All whitespace
    }

    if (line[firstNonWs] === '[') {
      this.parseHeader(line)
    } else {
      this.parseKeyValue(line)
    }
  }

  stripComment(line) {
    let inString = false
    let stringChar = null
    let result = ''

    for (let i = 0; i < line.length; i++) {
      const ch = line[i]

      if (inString) {
        result += ch
        if (ch === stringChar && (stringChar === "'" || line[i - 1] !== '\\')) {
          inString = false
        }
      } else {
        if (ch === '"' || ch === "'") {
          inString = true
          stringChar = ch
          result += ch
        } else if (ch === '#' || ch === ';') {
          break
        } else {
          result += ch
        }
      }
    }

    return result
  }

  parseHeader(line) {
    const lineNum = this.lineNum + 1

    if (line.startsWith('[[')) {
      // Array of tables
      const closeIdx = line.indexOf(']]')
      if (closeIdx === -1) {
        throw this.error('unterminated table header')
      }

      const nameStr = line.substring(2, closeIdx).trim()
      const afterClose = line.substring(closeIdx + 2).trim()

      if (afterClose && !afterClose.startsWith('#') && !afterClose.startsWith(';')) {
        throw this.error('trailing text after a table header')
      }

      const path = this.parseDottedName(nameStr)
      this.setArrayOfTablesHeader(path)
      this.currentPath = path
    } else if (line.startsWith('[')) {
      // Table
      const closeIdx = line.indexOf(']')
      if (closeIdx === -1) {
        throw this.error('unterminated table header')
      }

      const nameStr = line.substring(1, closeIdx).trim()
      const afterClose = line.substring(closeIdx + 1).trim()

      if (afterClose && !afterClose.startsWith('#') && !afterClose.startsWith(';')) {
        throw this.error('trailing text after a table header')
      }

      const path = this.parseDottedName(nameStr)
      this.setTableHeader(path)
      this.currentPath = path
    }
  }

  parseDottedName(str) {
    const parts = []
    let current = ''

    for (let i = 0; i < str.length; i++) {
      const ch = str[i]

      if (ch === '.') {
        if (current.trim() === '') {
          throw this.error('expected a name')
        }
        parts.push(this.parseName(current.trim()))
        current = ''
      } else {
        current += ch
      }
    }

    if (current.trim() === '') {
      throw this.error('expected a name')
    }
    parts.push(this.parseName(current.trim()))

    return parts
  }

  parseName(str) {
    if (str.startsWith('"')) {
      return this.parseBasicString(str, true)
    } else if (str.startsWith("'")) {
      return this.parseLiteralString(str, true)
    } else {
      // Bare word
      if (!/^[A-Za-z0-9_-]+$/.test(str)) {
        throw this.error('expected a name')
      }
      return str
    }
  }

  parseKeyValue(line) {
    const eqIdx = line.indexOf('=')
    if (eqIdx === -1) {
      throw this.error('expected key = value')
    }

    const keyStr = line.substring(0, eqIdx).trim()
    const valueStr = line.substring(eqIdx + 1)

    const path = this.parseDottedName(keyStr)
    const value = this.parseValue(valueStr.trimStart())

    this.setValue(path, value.value, value.afterValue)
  }

  parseValue(str) {
    if (str === '') {
      throw this.error('expected a value')
    }

    if (str === 'true') {
      return { value: true, afterValue: '' }
    }
    if (str === 'false') {
      return { value: false, afterValue: '' }
    }

    if (str.startsWith('"')) {
      return this.parseBasicStringValue(str)
    }
    if (str.startsWith("'")) {
      return this.parseLiteralStringValue(str)
    }
    if (str.startsWith('[')) {
      return this.parseArrayValue(str)
    }
    if (str.startsWith('{')) {
      return this.parseInlineTableValue(str)
    }

    // Try parsing number
    const numberMatch = str.match(/^[+\-]?\d[\d_]*(?:\.\d[\d_]*)?(?:[eE][+\-]?\d[\d_]*)?/)
    if (numberMatch) {
      const numStr = numberMatch[0]
      const afterNum = str.substring(numStr.length)

      // Check for # without whitespace
      if (afterNum.length > 0 && afterNum[0] === '#') {
        throw this.error(`invalid value ${numStr}#`)
      }

      const afterTrimmed = afterNum.trimStart()
      if (afterTrimmed && !afterTrimmed.startsWith('#') && !afterTrimmed.startsWith(';')) {
        throw this.error('trailing text after a value')
      }

      const cleanNum = numStr.replace(/_/g, '')
      if (cleanNum.includes('.') || cleanNum.toLowerCase().includes('e')) {
        return { value: parseFloat(cleanNum), afterValue: afterTrimmed }
      } else {
        return { value: parseInt(cleanNum, 10), afterValue: afterTrimmed }
      }
    }

    // Try parsing bare word (invalid value)
    const bareMatch = str.match(/^[A-Za-z_]+/)
    if (bareMatch) {
      throw this.error(`invalid value ${bareMatch[0]}`)
    }

    throw this.error('expected a value')
  }

  parseBasicStringValue(str) {
    if (str[0] !== '"') {
      throw this.error('expected a value')
    }

    let result = ''
    let i = 1
    let closed = false

    while (i < str.length) {
      const ch = str[i]

      if (ch === '\\') {
        if (i + 1 >= str.length) {
          throw this.error('unterminated string')
        }

        const next = str[i + 1]
        if (next === '"') {
          result += '"'
          i += 2
        } else if (next === '\\') {
          result += '\\'
          i += 2
        } else if (next === 'n') {
          result += '\n'
          i += 2
        } else if (next === 't') {
          result += '\t'
          i += 2
        } else if (next === 'r') {
          result += '\r'
          i += 2
        } else if (next === '0') {
          result += '\0'
          i += 2
        } else if (next === 'u') {
          if (i + 5 >= str.length) {
            throw this.error(`invalid escape \\u`)
          }
          const hex = str.substring(i + 2, i + 6)
          if (!/^[0-9a-fA-F]{4}$/.test(hex)) {
            throw this.error(`invalid escape \\u`)
          }
          result += String.fromCharCode(parseInt(hex, 16))
          i += 6
        } else {
          throw this.error(`invalid escape \\${next}`)
        }
      } else if (ch === '"') {
        closed = true
        i++
        break
      } else {
        result += ch
        i++
      }
    }

    if (!closed) {
      throw this.error('unterminated string')
    }

    const afterStr = str.substring(i).trimStart()
    if (afterStr && !afterStr.startsWith('#') && !afterStr.startsWith(';')) {
      throw this.error('trailing text after a value')
    }

    return { value: result, afterValue: afterStr }
  }

  parseLiteralStringValue(str) {
    if (str[0] !== "'") {
      throw this.error('expected a value')
    }

    let result = ''
    let i = 1
    let closed = false

    while (i < str.length) {
      const ch = str[i]

      if (ch === "'") {
        closed = true
        i++
        break
      } else {
        result += ch
        i++
      }
    }

    if (!closed) {
      throw this.error('unterminated string')
    }

    const afterStr = str.substring(i).trimStart()
    if (afterStr && !afterStr.startsWith('#') && !afterStr.startsWith(';')) {
      throw this.error('trailing text after a value')
    }

    return { value: result, afterValue: afterStr }
  }

  parseBasicString(str, isName = false) {
    if (str[0] !== '"') {
      throw this.error('expected a name')
    }

    let result = ''
    let i = 1
    let closed = false

    while (i < str.length) {
      const ch = str[i]

      if (ch === '\\') {
        if (i + 1 >= str.length) {
          throw this.error('unterminated string')
        }

        const next = str[i + 1]
        if (next === '"') {
          result += '"'
          i += 2
        } else if (next === '\\') {
          result += '\\'
          i += 2
        } else if (next === 'n') {
          result += '\n'
          i += 2
        } else if (next === 't') {
          result += '\t'
          i += 2
        } else if (next === 'r') {
          result += '\r'
          i += 2
        } else if (next === '0') {
          result += '\0'
          i += 2
        } else if (next === 'u') {
          if (i + 5 >= str.length) {
            throw this.error(`invalid escape \\u`)
          }
          const hex = str.substring(i + 2, i + 6)
          if (!/^[0-9a-fA-F]{4}$/.test(hex)) {
            throw this.error(`invalid escape \\u`)
          }
          result += String.fromCharCode(parseInt(hex, 16))
          i += 6
        } else {
          throw this.error(`invalid escape \\${next}`)
        }
      } else if (ch === '"') {
        closed = true
        i++
        break
      } else {
        result += ch
        i++
      }
    }

    if (!closed) {
      throw this.error('unterminated string')
    }

    return result
  }

  parseLiteralString(str, isName = false) {
    if (str[0] !== "'") {
      throw this.error('expected a name')
    }

    let result = ''
    let i = 1
    let closed = false

    while (i < str.length) {
      const ch = str[i]

      if (ch === "'") {
        closed = true
        i++
        break
      } else {
        result += ch
        i++
      }
    }

    if (!closed) {
      throw this.error('unterminated string')
    }

    return result
  }

  parseArrayValue(str) {
    if (str[0] !== '[') {
      throw this.error('expected a value')
    }

    const array = []
    let i = 1

    while (i < str.length && str[i] !== ']') {
      // Skip whitespace and comments
      while (i < str.length && /[\s]/.test(str[i])) {
        i++
      }

      if (i >= str.length || str[i] === ']') {
        break
      }

      // Skip comments inside arrays
      if (str[i] === '#' || str[i] === ';') {
        while (i < str.length && str[i] !== ']') {
          i++
        }
        continue
      }

      // Parse value
      const remaining = str.substring(i)
      const val = this.parseValue(remaining)
      array.push(val.value)

      i += remaining.length - val.afterValue.length

      // Skip whitespace and comments after value
      while (i < str.length && /[\s]/.test(str[i])) {
        i++
      }

      // Check for comma or closing bracket
      if (i < str.length && str[i] === ',') {
        i++
        // Skip whitespace after comma
        while (i < str.length && /[\s]/.test(str[i])) {
          i++
        }
        // Check for trailing comma before ]
        if (i < str.length && str[i] === ']') {
          i++
          break
        }
      } else if (i < str.length && str[i] === ']') {
        i++
        break
      } else if (i < str.length) {
        throw this.error('expected a value')
      }
    }

    if (i >= str.length || str[i] !== ']') {
      throw this.error('unterminated array')
    }

    i++
    const afterArray = str.substring(i).trimStart()
    if (afterArray && !afterArray.startsWith('#') && !afterArray.startsWith(';')) {
      throw this.error('trailing text after a value')
    }

    return { value: array, afterValue: afterArray }
  }

  parseInlineTableValue(str) {
    if (str[0] !== '{') {
      throw this.error('expected a value')
    }

    const obj = {}
    let i = 1

    while (i < str.length && str[i] !== '}') {
      // Skip whitespace
      while (i < str.length && /[\s]/.test(str[i])) {
        i++
      }

      if (i >= str.length || str[i] === '}') {
        break
      }

      // Parse key
      let keyStr = ''
      if (str[i] === '"' || str[i] === "'") {
        const quote = str[i]
        i++
        while (i < str.length && str[i] !== quote) {
          if (str[i] === '\\' && i + 1 < str.length) {
            keyStr += str[i] + str[i + 1]
            i += 2
          } else {
            keyStr += str[i]
            i++
          }
        }
        if (i >= str.length) {
          throw this.error('unterminated string')
        }
        i++
        if (quote === '"') {
          keyStr = this.parseBasicString('"' + keyStr + '"', true)
        } else {
          keyStr = this.parseLiteralString("'" + keyStr + "'", true)
        }
      } else {
        while (i < str.length && /[A-Za-z0-9_-]/.test(str[i])) {
          keyStr += str[i]
          i++
        }
        if (!keyStr) {
          throw this.error('expected a name')
        }
      }

      // Skip whitespace
      while (i < str.length && /[\s]/.test(str[i])) {
        i++
      }

      // Expect =
      if (i >= str.length || str[i] !== '=') {
        throw this.error('expected = in an inline table')
      }
      i++

      // Skip whitespace
      while (i < str.length && /[\s]/.test(str[i])) {
        i++
      }

      // Parse value
      const remaining = str.substring(i)
      const val = this.parseValue(remaining)
      obj[keyStr] = val.value

      i += remaining.length - val.afterValue.length

      // Skip whitespace
      while (i < str.length && /[\s]/.test(str[i])) {
        i++
      }

      // Check for comma or closing bracket
      if (i < str.length && str[i] === ',') {
        i++
        // Skip whitespace after comma
        while (i < str.length && /[\s]/.test(str[i])) {
          i++
        }
      } else if (i < str.length && str[i] === '}') {
        i++
        break
      } else if (i < str.length) {
        throw this.error('expected key = value')
      }
    }

    if (i > str.length || str[i - 1] !== '}') {
      throw this.error('unterminated inline table')
    }

    const afterTable = str.substring(i).trimStart()
    if (afterTable && !afterTable.startsWith('#') && !afterTable.startsWith(';')) {
      throw this.error('trailing text after a value')
    }

    return { value: obj, afterValue: afterTable }
  }

  setTableHeader(path) {
    let target = this.root
    const fullPath = []

    for (let i = 0; i < path.length; i++) {
      const key = path[i]
      fullPath.push(key)

      if (target[key] === undefined) {
        target[key] = {}
      } else if (typeof target[key] !== 'object' || Array.isArray(target[key])) {
        const pathStr = fullPath.join('.')
        throw this.error(`${pathStr} is not a table`)
      }

      target = target[key]
    }

    // Check if this header was already explicitly set
    const pathStr = path.join('.')
    if (target.__explicit) {
      throw this.error(`table ${pathStr} is defined twice`)
    }

    target.__explicit = true
    this.current = target
  }

  setArrayOfTablesHeader(path) {
    let target = this.root
    const fullPath = []

    for (let i = 0; i < path.length - 1; i++) {
      const key = path[i]
      fullPath.push(key)

      if (target[key] === undefined) {
        target[key] = {}
      } else if (typeof target[key] !== 'object' || Array.isArray(target[key])) {
        const pathStr = fullPath.join('.')
        throw this.error(`${pathStr} is not a table`)
      }

      target = target[key]
    }

    const lastKey = path[path.length - 1]
    fullPath.push(lastKey)

    if (target[lastKey] === undefined) {
      target[lastKey] = []
    } else if (!Array.isArray(target[lastKey])) {
      const pathStr = fullPath.join('.')
      throw this.error(`${pathStr} is not an array of tables`)
    }

    const newTable = {}
    target[lastKey].push(newTable)
    this.current = newTable
  }

  setValue(path, value, afterValue) {
    let target = this.current
    const fullPath = []

    for (let i = 0; i < path.length - 1; i++) {
      const key = path[i]
      fullPath.push(key)

      if (target[key] === undefined) {
        target[key] = {}
      } else if (typeof target[key] !== 'object' || Array.isArray(target[key])) {
        const pathStr = fullPath.join('.')
        throw this.error(`${pathStr} is not a table`)
      }

      target = target[key]
    }

    const lastKey = path[path.length - 1]
    fullPath.push(lastKey)
    const pathStr = fullPath.join('.')

    if (target[lastKey] !== undefined) {
      throw this.error(`key ${pathStr} is defined twice`)
    }

    target[lastKey] = value
  }

  error(msg) {
    return new Error(`error: line ${this.lineNum + 1}: ${msg}`)
  }
}

// ============================================================================

function toJSON(obj, indent = 0) {
  const spaces = ' '.repeat(indent)
  const innerSpaces = ' '.repeat(indent + 2)

  if (obj === null) {
    return 'null'
  }

  if (typeof obj === 'boolean') {
    return obj ? 'true' : 'false'
  }

  if (typeof obj === 'number') {
    return String(obj)
  }

  if (typeof obj === 'string') {
    return JSON.stringify(obj)
  }

  if (Array.isArray(obj)) {
    if (obj.length === 0) {
      return '[]'
    }

    // Check if this is an array of tables
    if (obj.length > 0 && typeof obj[0] === 'object' && !Array.isArray(obj[0])) {
      let isArrayOfTables = true
      for (const item of obj) {
        if (typeof item !== 'object' || Array.isArray(item)) {
          isArrayOfTables = false
          break
        }
      }

      if (isArrayOfTables) {
        const items = obj.map(item => {
          const keys = Object.keys(item).filter(k => k !== '__explicit').sort()
          const pairs = keys.map(k => {
            return `${innerSpaces}  "${k}": ${toJSON(item[k], indent + 4)}`
          })
          return `${innerSpaces}{\n${pairs.join(',\n')}\n${innerSpaces}}`
        })
        return `[\n${items.join(',\n')}\n${spaces}]`
      }
    }

    const items = obj.map(item => `${innerSpaces}${toJSON(item, indent + 2)}`)
    return `[\n${items.join(',\n')}\n${spaces}]`
  }

  if (typeof obj === 'object') {
    const keys = Object.keys(obj).filter(k => k !== '__explicit').sort()

    if (keys.length === 0) {
      return '{}'
    }

    const pairs = keys.map(key => {
      return `${innerSpaces}"${key}": ${toJSON(obj[key], indent + 2)}`
    })

    return `{\n${pairs.join(',\n')}\n${spaces}}`
  }

  return 'null'
}

function toKeys(obj, prefix = '') {
  const keys = []

  // Get all keys and sort them
  const objKeys = Object.keys(obj).filter(k => k !== '__explicit').sort()

  for (const key of objKeys) {
    const value = obj[key]
    const path = prefix ? `${prefix}.${key}` : key

    if (Array.isArray(value)) {
      // Check if it's an array of tables
      if (value.length > 0 && typeof value[0] === 'object' && !Array.isArray(value[0])) {
        keys.push(`${path} array`)
        for (let i = 0; i < value.length; i++) {
          const subKeys = toKeysInner(value[i], `${path}[${i}]`)
          keys.push(...subKeys)
        }
      } else {
        keys.push(`${path} array`)
        for (let i = 0; i < value.length; i++) {
          const item = value[i]
          if (Array.isArray(item)) {
            keys.push(`${path}[${i}] array`)
          } else if (typeof item === 'object') {
            keys.push(`${path}[${i}] table`)
            const subKeys = toKeysInner(item, `${path}[${i}]`)
            keys.push(...subKeys)
          } else {
            const type = getType(item)
            keys.push(`${path}[${i}] ${type}`)
          }
        }
      }
    } else if (typeof value === 'object' && value !== null) {
      keys.push(`${path} table`)
      const subKeys = toKeysInner(value, path)
      keys.push(...subKeys)
    } else {
      const type = getType(value)
      keys.push(`${path} ${type}`)
    }
  }

  return keys.join('\n')
}

function toKeysInner(obj, prefix) {
  const keys = []
  const objKeys = Object.keys(obj).filter(k => k !== '__explicit').sort()

  for (const key of objKeys) {
    const value = obj[key]
    const path = `${prefix}.${key}`

    if (Array.isArray(value)) {
      if (value.length > 0 && typeof value[0] === 'object' && !Array.isArray(value[0])) {
        keys.push(`${path} array`)
        for (let i = 0; i < value.length; i++) {
          const subKeys = toKeysInner(value[i], `${path}[${i}]`)
          keys.push(...subKeys)
        }
      } else {
        keys.push(`${path} array`)
        for (let i = 0; i < value.length; i++) {
          const item = value[i]
          if (Array.isArray(item)) {
            keys.push(`${path}[${i}] array`)
          } else if (typeof item === 'object') {
            keys.push(`${path}[${i}] table`)
            const subKeys = toKeysInner(item, `${path}[${i}]`)
            keys.push(...subKeys)
          } else {
            const type = getType(item)
            keys.push(`${path}[${i}] ${type}`)
          }
        }
      }
    } else if (typeof value === 'object' && value !== null) {
      keys.push(`${path} table`)
      const subKeys = toKeysInner(value, path)
      keys.push(...subKeys)
    } else {
      const type = getType(value)
      keys.push(`${path} ${type}`)
    }
  }

  return keys
}

function getType(value) {
  if (typeof value === 'boolean') {
    return 'boolean'
  }
  if (typeof value === 'number') {
    if (Number.isInteger(value)) {
      return 'integer'
    }
    return 'float'
  }
  if (typeof value === 'string') {
    return 'string'
  }
  if (Array.isArray(value)) {
    return 'array'
  }
  if (typeof value === 'object' && value !== null) {
    return 'table'
  }
  return 'unknown'
}
